const sourceItems = $input.all();

function cleanText(value) {
  return String(value ?? '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractSearchTerm(inputUrl) {
  if (!inputUrl) return '';

  try {
    const url = new URL(inputUrl);
    return cleanText(url.searchParams.get('keywords') ?? '');
  } catch {
    return '';
  }
}

function createStableJobKey(job) {
  if (job.id) {
    return `linkedin:${String(job.id).trim()}`;
  }

  const fallback = [
    cleanText(job.title).toLowerCase(),
    cleanText(job.companyName).toLowerCase(),
    cleanText(job.location).toLowerCase(),
  ].join('|');

  return `linkedin:${fallback}`;
}

return sourceItems
  .map((item) => {
    const job = item.json;

    const jobUrl = cleanText(job.link);
    const applicationUrl = cleanText(job.applyUrl) || jobUrl;
    const description = cleanText(
      job.descriptionText || job.descriptionHtml,
    );

    return {
      json: {
        jobKey: createStableJobKey(job),
        source: 'LinkedIn',
        sourceJobId: cleanText(job.id),

        title: cleanText(job.title),
        company: cleanText(job.companyName),
        location: cleanText(job.location),

        postedAt: cleanText(job.postedAt),
        scrapedAt: new Date().toISOString(),

        jobUrl,
        applicationUrl,

        description,
        salary: cleanText(job.salary),
        employmentType: cleanText(job.employmentType),
        seniorityLevel: cleanText(job.seniorityLevel),
        jobFunction: cleanText(job.jobFunction),
        industries: cleanText(job.industries),

        applicantsCount: cleanText(job.applicantsCount),
        searchTerm: extractSearchTerm(job.inputUrl),
        sourceSearchUrl: cleanText(job.inputUrl),

        status: 'NEW',
      },
    };
  })
  .filter((item) => {
    const job = item.json;

    return (
      job.sourceJobId &&
      job.title &&
      job.company &&
      job.description &&
      job.jobUrl
    );
  });

const items = $input.all();
const seen = new Set();
const uniqueJobs = [];

for (const item of items) {
  const job = item.json;

  const duplicateKey =
    String(job.jobKey || '').trim() ||
    [
      String(job.title || '').trim().toLowerCase(),
      String(job.company || '').trim().toLowerCase(),
      String(job.location || '').trim().toLowerCase(),
    ].join('|');

  if (!duplicateKey || seen.has(duplicateKey)) {
    continue;
  }

  seen.add(duplicateKey);

  uniqueJobs.push({
    json: {
      ...job,
      duplicateKey,
    },
  });
}

return uniqueJobs;

const currentJobs = $('06 - Remove Duplicate Jobs').all();
const existingRows = $input.all();

const savedJobKeys = new Set(
  existingRows
    .map((item) => String(item.json.jobKey ?? '').trim())
    .filter(Boolean),
);

return currentJobs
  .filter((item) => {
    const jobKey = String(item.json.jobKey ?? '').trim();
    return jobKey && !savedJobKeys.has(jobKey);
  })
  .map((item) => ({
    json: {
      ...item.json,
      isPreviouslySaved: false,
    },
  }));

const jobs = $input.all();

const positiveKeywords = [
  'n8n',
  'make.com', 
  'zapier',
  'automation',
  'workflow',
  'ai integration',
  'ai agent',
  'llm',
  'openai',
  'prompt engineering',
  'rest api',
  'restful api',
  'webhook',
  'json',
  'wordpress',
  'woocommerce',
  'php',
  'laravel',
  'symfony',
  'javascript',
  'typescript',
  'react',
  'next.js',
  'node.js',
  'full stack',
  'fullstack',
  'web developer',
  'webentwickler',
  'frontend developer',
  'backend developer',
  'software developer',
  'integration',
  'process automation',
];

const strongNegativeKeywords = [
  'database administrator',
  'senior database engineer',
  'sap fi consultant',
  'pick-by-voice',
  'machine learning scientist',
  'security clearance',
  'top-secret clearance',
  'servicenow administrator',
];

function normalize(value) {
  return String(value ?? '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

return jobs
  .map((item) => {
    const job = item.json;

    const searchableText = normalize([
      job.title,
      job.description,
      job.jobFunction,
      job.industries,
      job.searchTerm,
    ].join(' '));

    const matchedKeywords = positiveKeywords.filter((keyword) =>
      searchableText.includes(keyword),
    );

    const blockedKeywords = strongNegativeKeywords.filter((keyword) =>
      searchableText.includes(keyword),
    );

    const isRelevant =
      matchedKeywords.length >= 2 &&
      blockedKeywords.length === 0;

    return {
      json: {
        ...job,
        prefilterMatchedKeywords: matchedKeywords,
        prefilterBlockedKeywords: blockedKeywords,
        prefilterScore: matchedKeywords.length,
        isRelevant,
      },
    };
  })
  .filter((item) => item.json.isRelevant);

const openAiResponse = $input.item.json;

const originalJob =
  $('12 - Build AI Match Prompt').item.json;

const aiResult =
  openAiResponse.output?.[0]?.content?.[0]?.text ?? null;

if (
  !aiResult ||
  typeof aiResult !== 'object' ||
  Array.isArray(aiResult)
) {
  throw new Error(
    `AI match result is missing or invalid for ${
      originalJob.jobKey ?? 'unknown job'
    }`,
  );
}

const technicalSkillsScore = Number(
  aiResult.technicalSkillsScore ?? 0,
);

const roleRelevanceScore = Number(
  aiResult.roleRelevanceScore ?? 0,
);

const experienceScore = Number(
  aiResult.experienceScore ?? 0,
);

const languageScore = Number(
  aiResult.languageScore ?? 0,
);

const locationScore = Number(
  aiResult.locationScore ?? 0,
);

const employmentScore = Number(
  aiResult.employmentScore ?? 0,
);

const calculatedScore =
  technicalSkillsScore +
  roleRelevanceScore +
  experienceScore +
  languageScore +
  locationScore +
  employmentScore;

const parsedResult = Object.assign({}, originalJob, {
  technicalSkillsScore,
  roleRelevanceScore,
  experienceScore,
  languageScore,
  locationScore,
  employmentScore,

  aiMatchScore: Number(
    aiResult.matchScore ?? calculatedScore,
  ),

  calculatedMatchScore: calculatedScore,

  recommendation: String(
    aiResult.recommendation ?? 'SKIP',
  ),

  applicationPriority: String(
    aiResult.applicationPriority ?? 'NONE',
  ),

  matchingSkills: Array.isArray(aiResult.matchingSkills)
    ? aiResult.matchingSkills
    : [],

  missingRequiredSkills: Array.isArray(
    aiResult.missingRequiredSkills,
  )
    ? aiResult.missingRequiredSkills
    : [],

  missingOptionalSkills: Array.isArray(
    aiResult.missingOptionalSkills,
  )
    ? aiResult.missingOptionalSkills
    : [],

  languageAssessment: String(
    aiResult.languageAssessment ?? '',
  ),

  locationAssessment: String(
    aiResult.locationAssessment ?? '',
  ),

  mainStrengths: Array.isArray(aiResult.mainStrengths)
    ? aiResult.mainStrengths
    : [],

  mainRisks: Array.isArray(aiResult.mainRisks)
    ? aiResult.mainRisks
    : [],

  summary: String(aiResult.summary ?? ''),

  aiAnalysedAt: new Date().toISOString(),
});

return {
  json: parsedResult,
};

const input = $input.item.json;

const allowedRecommendations = new Set([
  'STRONG_MATCH',
  'GOOD_MATCH',
  'POSSIBLE_MATCH',
  'SKIP',
]);

const allowedPriorities = new Set([
  'HIGH',
  'MEDIUM',
  'LOW',
  'NONE',
]);

function clamp(value, min, max) {
  const number = Number(value);

  if (!Number.isFinite(number)) {
    return min;
  }

  return Math.min(
    max,
    Math.max(min, Math.round(number)),
  );
}

const technicalSkillsScore = clamp(
  input.technicalSkillsScore,
  0,
  40,
);

const roleRelevanceScore = clamp(
  input.roleRelevanceScore,
  0,
  20,
);

const experienceScore = clamp(
  input.experienceScore,
  0,
  15,
);

const languageScore = clamp(
  input.languageScore,
  0,
  10,
);

const locationScore = clamp(
  input.locationScore,
  0,
  10,
);

const employmentScore = clamp(
  input.employmentScore,
  0,
  5,
);

const validatedMatchScore =
  technicalSkillsScore +
  roleRelevanceScore +
  experienceScore +
  languageScore +
  locationScore +
  employmentScore;

const recommendationValue = String(
  input.recommendation ?? '',
);

const recommendation =
  allowedRecommendations.has(recommendationValue)
    ? recommendationValue
    : 'SKIP';

const priorityValue = String(
  input.applicationPriority ?? '',
);

const applicationPriority =
  allowedPriorities.has(priorityValue)
    ? priorityValue
    : 'NONE';

const validatedResult = Object.assign({}, input, {
  technicalSkillsScore,
  roleRelevanceScore,
  experienceScore,
  languageScore,
  locationScore,
  employmentScore,

  matchScore: validatedMatchScore,
  recommendation,
  applicationPriority,

  scoreValidationPassed:
    Number(input.aiMatchScore) === validatedMatchScore,

  matchingSkills: Array.isArray(input.matchingSkills)
    ? input.matchingSkills
    : [],

  missingRequiredSkills: Array.isArray(
    input.missingRequiredSkills,
  )
    ? input.missingRequiredSkills
    : [],

  missingOptionalSkills: Array.isArray(
    input.missingOptionalSkills,
  )
    ? input.missingOptionalSkills
    : [],

  mainStrengths: Array.isArray(input.mainStrengths)
    ? input.mainStrengths
    : [],

  mainRisks: Array.isArray(input.mainRisks)
    ? input.mainRisks
    : [],

  validationStatus: 'VALID',
});

return {
  json: validatedResult,
};

const input = $input.item.json;

const searchConfig =
  $('02 - Define Search Configuration')
    .first()
    .json;

const minimumMatchScore =
  Number(searchConfig.minimumMatchScore) || 60;

const baseScore = Number(input.matchScore ?? 0);

let preferenceAdjustment = 0;

const searchableText = [
  input.title,
  input.description,
  input.locationAssessment,
]
  .filter(Boolean)
  .join(' ')
  .toLowerCase();

// Remote or home-office preference bonus
if (
  searchableText.includes('remote') ||
  searchableText.includes('home office') ||
  searchableText.includes('homeoffice')
) {
  preferenceAdjustment += 2;
}

// Automation and AI preference bonus
if (
  searchableText.includes('n8n') ||
  searchableText.includes('workflow automation') ||
  searchableText.includes('ai integration') ||
  searchableText.includes('llm')
) {
  preferenceAdjustment += 3;
}

// WordPress and WooCommerce preference bonus
if (
  searchableText.includes('wordpress') ||
  searchableText.includes('woocommerce')
) {
  preferenceAdjustment += 2;
}

// Language penalty for requirements above candidate level
if (
  searchableText.includes('german c1') ||
  searchableText.includes('deutsch c1') ||
  searchableText.includes('native german') ||
  searchableText.includes('muttersprache deutsch')
) {
  preferenceAdjustment -= 5;
}

const finalMatchScore = Math.max(
  0,
  Math.min(100, baseScore + preferenceAdjustment),
);

let scoreBand = 'LOW';

if (finalMatchScore >= 85) {
  scoreBand = 'EXCELLENT';
} else if (finalMatchScore >= 75) {
  scoreBand = 'STRONG';
} else if (finalMatchScore >= 60) {
  scoreBand = 'RELEVANT';
}

const result = Object.assign({}, input, {
  baseMatchScore: baseScore,
  preferenceAdjustment,
  finalMatchScore,
  scoreBand,
  meetsMinimumScore:
    finalMatchScore >= minimumMatchScore,
  minimumRequiredScore: minimumMatchScore,
});

return {
  json: result,
};

const priorityWeight = {
  HIGH: 3,
  MEDIUM: 2,
  LOW: 1,
  NONE: 0,
};

const recommendationWeight = {
  STRONG_MATCH: 4,
  GOOD_MATCH: 3,
  POSSIBLE_MATCH: 2,
  SKIP: 1,
};

const items = $input.all();

const eligibleJobs = items.filter((item) => {
  return item.json.meetsMinimumScore === true;
});

eligibleJobs.sort((a, b) => {
  const jobA = a.json;
  const jobB = b.json;

  const scoreDifference =
    Number(jobB.finalMatchScore ?? 0) -
    Number(jobA.finalMatchScore ?? 0);

  if (scoreDifference !== 0) {
    return scoreDifference;
  }

  const priorityDifference =
    Number(priorityWeight[jobB.applicationPriority] ?? 0) -
    Number(priorityWeight[jobA.applicationPriority] ?? 0);

  if (priorityDifference !== 0) {
    return priorityDifference;
  }

  const recommendationDifference =
    Number(recommendationWeight[jobB.recommendation] ?? 0) -
    Number(recommendationWeight[jobA.recommendation] ?? 0);

  if (recommendationDifference !== 0) {
    return recommendationDifference;
  }

  const dateA = Date.parse(jobA.postedAt ?? '') || 0;
  const dateB = Date.parse(jobB.postedAt ?? '') || 0;

  return dateB - dateA;
});

return eligibleJobs.map((item, index) => {
  const rankedJob = Object.assign({}, item.json, {
    rankingPosition: index + 1,
  });

  return {
    json: rankedJob,
  };
});

const searchConfig =
  $('02 - Define Search Configuration')
    .first()
    .json;

const maximumFinalJobs =
  Number(searchConfig.maximumFinalJobs) || 15;

const selectedAt = new Date().toISOString();

const items = $input
  .all()
  .slice(0, maximumFinalJobs);

return items.map((item, index) => {
  const selectedJob = Object.assign({}, item.json, {
    rankingPosition: index + 1,
    selectedForFinalList: true,
    selectedAt,
  });

  return {
    json: selectedJob,
  };
});

const input = $input.item.json;

function joinList(value) {
  return Array.isArray(value)
    ? value.filter(Boolean).join(', ')
    : '';
}

const missingRequiredSkills = Array.isArray(
  input.missingRequiredSkills,
)
  ? input.missingRequiredSkills
  : [];

const missingOptionalSkills = Array.isArray(
  input.missingOptionalSkills,
)
  ? input.missingOptionalSkills
  : [];

const missingSkills = missingRequiredSkills.concat(
  missingOptionalSkills,
);

return {
  json: {
    jobKey: String(input.jobKey ?? ''),
    foundAt: String(
      input.selectedAt ?? new Date().toISOString(),
    ),

    source: String(input.source ?? ''),
    sourceJobId: String(input.sourceJobId ?? ''),

    title: String(input.title ?? ''),
    company: String(input.company ?? ''),
    location: String(input.location ?? ''),

    postedAt: String(input.postedAt ?? ''),
    employmentType: String(input.employmentType ?? ''),
    seniorityLevel: String(input.seniorityLevel ?? ''),
    salary: String(input.salary ?? ''),

    matchScore: Number(input.finalMatchScore ?? 0),
    recommendation: String(input.recommendation ?? ''),
    applicationPriority: String(
      input.applicationPriority ?? '',
    ),

    matchingSkills: joinList(input.matchingSkills),
    missingSkills: joinList(missingSkills),

    summary: String(input.summary ?? ''),

    jobUrl: String(input.jobUrl ?? ''),
    applicationUrl: String(
      input.applicationUrl || input.jobUrl || '',
    ),

    searchTerm: String(input.searchTerm ?? ''),
    status: 'NEW',

    appliedAt: '',
    notes: '',
  },
};

const items = $input.all();

function getCleanJobUrl(job) {
  if (
    job.source === 'LinkedIn' &&
    job.sourceJobId
  ) {
    return `https://www.linkedin.com/jobs/view/${job.sourceJobId}`;
  }

  return String(
    job.applicationUrl || job.jobUrl || '',
  );
}

const jobs = items
  .map((item) => item.json)
  .sort(
    (a, b) =>
      Number(b.matchScore ?? 0) -
      Number(a.matchScore ?? 0),
  );

const date = new Intl.DateTimeFormat('de-DE', {
  dateStyle: 'medium',
  timeZone: 'Europe/Berlin',
}).format(new Date());

const lines = jobs.map((job, index) => {
  const score = Number(job.matchScore ?? 0);
  const title = String(job.title ?? 'Unknown role');
  const company = String(job.company ?? 'Unknown company');
  const location = String(job.location ?? '');
  const priority = String(
    job.applicationPriority ?? '',
  );
  const url = getCleanJobUrl(job);

  return [
    `${index + 1}. ${score}% — ${title}`,
    `🏢 ${company}`,
    location ? `📍 ${location}` : '',
    priority ? `🎯 Priority: ${priority}` : '',
    url ? `🔗 ${url}` : '',
  ]
    .filter(Boolean)
    .join('\n');
});

const telegramMessage = [
  `🤖 Daily AI Job Matches`,
  `📅 ${date}`,
  '',
  `Found ${jobs.length} new matching jobs.`,
  '',
  lines.join('\n\n'),
  '',
  `✅ Full details saved in Google Sheets.`,
].join('\n');

return [
  {
    json: {
      telegramMessage,
      matchedJobCount: jobs.length,
      generatedAt: new Date().toISOString(),
    },
  },
];

const items = $input.all();

function decodeHtml(value) {
  return String(value ?? '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

function buildDescription(job) {
  const sections = Array.isArray(job.textSections)
    ? job.textSections
    : [];

  const sectionText = sections
    .map((section) => {
      const title = decodeHtml(section.title);
      const content = decodeHtml(section.content);

      return [title, content]
        .filter(Boolean)
        .join(': ');
    })
    .filter(Boolean)
    .join(' ');

  return sectionText || decodeHtml(job.textSnippet);
}

function formatSalary(salary) {
  if (!salary || typeof salary !== 'object') {
    return '';
  }

  const currency = String(
    salary.currency ?? salary.currencyIso ?? '',
  ).trim();

  const min = Number(salary.min);
  const max = Number(salary.max);
  const period = String(salary.period ?? '').trim();

  if (Number.isFinite(min) && Number.isFinite(max)) {
    return `${currency}${min.toLocaleString('de-DE')} - ${currency}${max.toLocaleString('de-DE')} per ${period}`;
  }

  if (Number.isFinite(min)) {
    return `From ${currency}${min.toLocaleString('de-DE')} per ${period}`;
  }

  if (Number.isFinite(max)) {
    return `Up to ${currency}${max.toLocaleString('de-DE')} per ${period}`;
  }

  return '';
}

function mapWorkMode(value) {
  const mode = String(value ?? '').trim();

  if (mode === '2') {
    return 'Remote/Hybrid';
  }

  if (mode === '1') {
    return 'Hybrid';
  }

  if (mode === '0') {
    return 'On-site';
  }

  return '';
}

return items
  .map((item) => {
    const job = item.json;

    const sourceJobId = String(job.id ?? '').trim();
    const jobUrl = String(job.url ?? '').trim();

    const company =
      typeof job.company === 'object'
        ? String(job.company.name ?? '').trim()
        : String(job.company ?? '').trim();

    const location =
      typeof job.location === 'object'
        ? String(job.location.location ?? '').trim()
        : String(job.location ?? '').trim();

    const description = buildDescription(job);

    const normalizedJob = {
      jobKey: sourceJobId
        ? `stepstone:${sourceJobId}`
        : `stepstone:${jobUrl}`,

      source: 'StepStone',
      sourceJobId,

      title: String(job.title ?? '').trim(),
      company,
      location,

      postedAt: String(job.datePosted ?? '').trim(),
      scrapedAt: new Date().toISOString(),

      jobUrl,
      applicationUrl: jobUrl,

      description,
      salary: formatSalary(job.salary),

      employmentType: '',
      seniorityLevel: '',
      jobFunction: '',
      industries: '',

      workMode: mapWorkMode(job.workFromHome),
      jobLanguage: String(job.offerLanguage ?? '').trim(),

      applicantsCount: '',
      searchTerm: 'WordPress Developer',
      sourceSearchUrl: '',

      status: 'NEW',
    };

    return {
      json: normalizedJob,
    };
  })
  .filter((item) => {
    const job = item.json;

    return (
      job.sourceJobId &&
      job.title &&
      job.company &&
      job.description &&
      job.jobUrl
    );
  });
